-- Generated by model/lib/sql/generate.mjs. Loads IMPORT Handling Factor from cells/IMPORT Handling Factor.csv in the folder of input cells. Two rows for one cell add up.
INSERT INTO "IMPORT Handling Factor" ("Temperature Zone", v, ver, is_deleted) SELECT coalesce(k0."Temperature Zone", throwIf(isNull(k0."Temperature Zone"), 'cells name a member Temperature Zone does not have')), sum(toFloat64(c.value)), toUnixTimestamp64Micro(now64(6)), 0
FROM file('cells/IMPORT Handling Factor.csv', 'CSVWithNames', '"Temperature Zone" String, "value" String') c LEFT JOIN "dim Temperature Zone" k0 ON k0.name = c."Temperature Zone"
GROUP BY ALL;
